with parsed as (select id, service, log_ts, level, latency_ms, status_code, coalesce(context['version'], 'unknown') as version_or_default, get_json_object(payload_json, '$.user.tier') as user_tier, context['region'] as region, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration as duration_sec, context['trace'] as trace from app_logs) select id, service, latency_ms, version_or_default, user_tier, duration_sec, trace, corr(latency_ms, status_code) over (partition by level) as corr_latency_ms_status_code, row_number() over (partition by level order by duration_sec desc, id) as row_seq, ntile(10) over (order by duration_sec, id) as duration_sec_bucket from parsed where duration_sec between 2.8 and 3.9
